import React from "react";
import { Link } from "react-router-dom";
import { FaUserInjured, FaFileInvoice, FaHome } from "react-icons/fa";

const Sidebar = () => {
    return (
        <div className="bg-dark text-white p-3 vh-100">
            <h4 className="text-center mb-4">🏥 HMS</h4>

            <ul className="nav flex-column">

                <li className="nav-item mb-2">
                    <Link className="nav-link text-white" to="/dashboard">
                        <FaHome /> Dashboard
                    </Link>
                </li>

                <li className="nav-item mb-2">
                    <Link className="nav-link text-white" to="/patients">
                        <FaUserInjured /> Patients
                    </Link>
                </li>

                <li className="nav-item mb-2">
                    <Link className="nav-link text-white" to="/billing">
                        <FaFileInvoice /> Billing
                    </Link>
                </li>

            </ul>
        </div>
    );
};

export default Sidebar;
